178	   *  or one at the rate of the grade they had on its date): then the sum of the dues there are. */
179	  private readonly dueByPerson = computed(() => {
180	    const out = new Map<number, number | null>();
181	    const floor = cents(this.session.floor());
182	    const late = this.lateness();
183	    for (const p of this.people()) {
184	      const dues = this.claimsOf(p.id).filter(this.countsLive())
