362	  /** The last statement's due-total: blank with none, n/a when it was n/a. */
363	  protected statedTotalOf(p: Person): string {
364	    return p.statementCount === 0 ? '' : (p.statedTotal ?? 'n/a');
365	  }
366	
367	  /** Take a statement of a person; the row then shows it and their claims as bound now. */
368	  protected async statement(p: Person): Promise<void> {
369	    this.clearRowError(p.id);
370	    const sheetId = this.session.sheetId();
371	    if (!sheetId) return;
372	    try {
373	      const taken = await this.api.statement(sheetId, p.id);
374	      if (this.session.sheetId() !== sheetId) return;
375	      this.taken(taken.person);
376	      this.claims.update((cs) => [...cs.filter((c) => c.personId !== p.id), ...taken.claims].sort((a, b) => b.id - a.id));
377	    } catch (e) {
378	      this.rowErrors.update((errs) => ({ ...errs, [p.id]: statementError(e) }));
379	    }
380	  }
381	
382	  /** Retire a person from a date (blank: the sheet's today); the row then shows them retired. */
383	  protected async retire(p: Person, from: string): Promise<void> {
384	    this.clearRowError(p.id);
385	    const sheetId = this.session.sheetId();
386	    if (!sheetId) return;
387	    try {
388	      const retired = await this.api.retire(sheetId, p.id, from.trim());
389	      if (this.session.sheetId() === sheetId) this.taken(retired);
390	    } catch (e) {
391	      this.rowErrors.update((errs) => ({ ...errs, [p.id]: retireError(e) }));
392	    }
393	  }
394	
395	  /** Put a person on hold, or take them off it when held; the row then shows the new state. */
396	  protected async hold(p: Person): Promise<void> {
397	    this.clearRowError(p.id);
398	    const sheetId = this.session.sheetId();
399	    if (!sheetId) return;
400	    try {
401	      const saved = await this.api.hold(sheetId, p.id, !p.held);
402	      if (this.session.sheetId() === sheetId) this.taken(saved);
403	    } catch (e) {
404	      this.rowErrors.update((errs) => ({ ...errs, [p.id]: holdError(e) }));
405	    }
406	  }
407	
408	  protected clearRowError(id: number): void {
409	    this.rowErrors.update(({ [id]: _, ...rest }) => rest);
410	    this.patronErrors.update(({ [id]: _, ...rest }) => rest);
411	  }
412	
413	  /** Take in a rate just set, in place of the grade's old one for the same from-date. */
414	  protected rateSaved(rate: Rate): void {
415	    this.rates.update((rs) => [...rs.filter((r) => r.grade !== rate.grade || r.from !== rate.from), rate]);
416	  }
417	
418	  /** Take in a period just added or closed, in its place by from-date. */
419	  protected periodSaved(period: Period): void {
420	    this.periods.update((ps) => [...ps.filter((p) => p.id !== period.id), period].sort((a, b) => a.from.localeCompare(b.from)));
421	  }
422	
423	  /** Take in a claim just added (listed first, as the newest) or saved (in its place). */
424	  protected claimSaved(claim: Claim): void {
425	    this.claims.update((cs) => cs.some((c) => c.id === claim.id)
426	      ? cs.map((c) => (c.id === claim.id ? claim : c))
427	      : [claim, ...cs].sort((a, b) => b.id - a.id));
428	  }
429	
430	  protected cancel(): void {
431	    this.reset();
432	  }
433	
434	  protected async submit(): Promise<void> {
435	    if (this.submitting) return;
436	    this.error.set(null);
437	    const sheetId = this.session.sheetId();
438	    if (!sheetId) return;
439	    const value = this.form.getRawValue();
440	    if (!value.name.trim()) {
441	      this.error.set('Enter a name.');
442	      return;
443	    }
444	    if (!(GRADES as readonly string[]).includes(value.grade)) {
445	      this.error.set('Choose a grade.');
446	      return;
447	    }
448	    const editing = this.editingId();
449	    this.submitting = true;
450	    try {
451	      if (editing === null) {
452	        const added = await this.api.add(sheetId, { name: value.name, grade: value.grade });
453	        if (this.session.sheetId() === sheetId) this.people.update((ps) => [...ps, added]);
454	      } else {
455	        const saved = await this.api.update(sheetId, editing,
456	          { ...value, gradeFrom: value.gradeFrom.trim() || null, version: this.editingVersion });
457	        if (this.session.sheetId() === sheetId) this.taken(saved);
458	      }
459	      this.reset();
460	    } catch (e) {
461	      if (editing !== null && isStale(e)) await this.reloadEditing(sheetId, editing);
462	      this.error.set(personError(e));
463	    } finally {
464	      this.submitting = false;
465	    }
466	  }
467	
468	  /** Quick-add a DRAFT claim by name; the person is added first (grade A) when new. */
469	  protected async quickAdd(): Promise<void> {
470	    if (this.quickAdding) return;
471	    this.quickError.set(null);
472	    const sheetId = this.session.sheetId();
473	    if (!sheetId) return;
474	    const value = this.quickForm.getRawValue();
475	    const amount = value.amount.trim();
476	    if (!value.name.trim()) {
477	      this.quickError.set('Enter a name.');
478	      return;
479	    }
480	    if (!AMOUNT_PATTERN.test(amount)) {
481	      this.quickError.set('Enter an amount of 0.00 or more with up to two decimals.');
482	      return;
483	    }
484	    this.quickAdding = true;
485	    try {
486	      const added = await this.claimsApi.quickAdd(sheetId, { name: value.name, amount });
487	      if (this.session.sheetId() !== sheetId) return;
488	      if (added.personAdded) this.people.update((ps) => [...ps.filter((p) => p.id !== added.person.id), added.person]);
489	      else this.taken(added.person);
490	      this.claimSaved(added.claim);
491	      this.quickForm.reset({ name: '', amount: '' }, { emitEvent: false });
492	    } catch (e) {
493	      this.quickError.set(quickAddError(e));
494	    } finally {
495	      this.quickAdding = false;
496	    }
497	  }
498	
499	  /** Take in a person as the store now holds them, in place of the old row. */
500	  private taken(person: Person): void {
501	    this.people.update((ps) => ps.map((p) => (p.id === person.id ? person : p)));
502	  }
503	
504	  /** After a save refused as stale, show the person's current values in the row and the open
505	   *  editor, which then edits that version. */
506	  private async reloadEditing(sheetId: string, id: number): Promise<void> {
507	    try {
508	      const current = await this.api.get(sheetId, id);
509	      if (this.session.sheetId() !== sheetId || this.editingId() !== id) return;
510	      this.taken(current);
511	      this.editingVersion = current.version;
512	      this.form.setValue({ name: current.name, grade: this.gradeOf(current), gradeFrom: this.form.getRawValue().gradeFrom },
513	        { emitEvent: false });
514	    } catch {
515	      // the error shown already says the save was refused
516	    }
517	  }
518	
519	  private reset(): void {
520	    this.editingId.set(null);
521	    this.form.reset({ name: '', grade: 'A', gradeFrom: '' });
522	    this.error.set(null);
523	  }
524	
525	  private async read(sheetId: string): Promise<void> {
526	    const seq = ++this.readSeq;
527	    try {
528	      const [people, claims, rates, periods] = await Promise.all([
529	        this.api.list(sheetId), this.claimsApi.list(sheetId), this.ratesApi.list(sheetId), this.periodsApi.list(sheetId)]);
530	      if (seq === this.readSeq) {
531	        this.rates.set(rates);
532	        this.periods.set(periods);
533	        this.claims.set(claims);
534	        this.people.set(people);
535	      }
536	    } catch {
537	      if (seq === this.readSeq) this.error.set('Something went wrong loading people; try again.');
538	    }
539	  }
540	}
